<?php $logo=dj_logo_url($context);$menu=$context->menu('primary');$menu=is_array($menu)?$menu:[];?>
<header class="dj-header"><a class="dj-brand" href="/"><?php if($logo!==''):?><img src="<?= $context->e($logo) ?>" alt="<?= $context->e($context->get('site_name','')) ?>"><?php else:?><span><?= $context->e($context->get('site_name','清静无为')) ?></span><small>· Daojia</small><?php endif;?></a><button class="dj-menu-btn" type="button" aria-label="打开导航" aria-expanded="false">☰</button><nav class="dj-nav" aria-label="主导航"><?php if($menu===[]):?><a href="/">首页</a><a href="/articles">典籍</a><?php else:foreach($menu as $m):?><a href="<?= $context->e((string)($m['url']??'/')) ?>"<?= !empty($m['current'])?' aria-current="page"':'' ?>><?= $context->e((string)($m['label']??'')) ?></a><?php endforeach;endif;?></nav></header>